// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 20 ether);

        // First call at timestamp 100
        vm.warp(100);
        vm.prank(alice);
        c.fall{value: 10 ether}();

        // Attempt second call at timestamp 100 (same second)
        vm.warp(100);
        vm.prank(alice);
        bool ok;
        try c.fall{value: 10 ether}() { ok = true; } catch { ok = false; }

        // Reference sets pastBlockTime = 101, so require(100 > 101) fails => ok false
        // Bug sets pastBlockTime = 100, so require(100 > 100) fails => ok false
        // But the difference manifests on the third call:

        // Third call at timestamp 101
        vm.warp(101);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        try c.fall{value: 10 ether}() { ok = true; } catch { ok = false; }

        // Reference: pastBlockTime = 102, call succeeds => ok true
        // Bug: pastBlockTime = 100, call succeeds => ok true
        // No difference here. Need different scenario.

        // Reset: deploy fresh
        c = new C();

        // First call at timestamp 100
        vm.warp(100);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        c.fall{value: 10 ether}();

        // Second call at timestamp 100 (same second)
        vm.warp(100);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        bool ok2;
        try c.fall{value: 10 ether}() { ok2 = true; } catch { ok2 = false; }

        // Reference: pastBlockTime = 101, require(100 > 101) fails => ok2 false
        // Bug: pastBlockTime = 100, require(100 > 100) fails => ok2 false
        // Both false, but we can check pastBlockTime after first call:
        // Not observable because pastBlockTime is public and we can read it

        // Let's read pastBlockTime after first call:
        vm.warp(100);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        c.fall{value: 10 ether}();

        uint afterFirst = c.pastBlockTime();
        // Reference: 101, Bug: 100

        assertTrue(afterFirst == 101, "pastBlockTime should be timestamp+1");
        // Reference: 101 == 101 passes; Bug: 100 == 101 fails
    }
}

