// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initial state: pastBlockTime = 0
        // We'll make first call at block.timestamp = 1
        vm.warp(1);
        vm.deal(address(this), 20 ether);

        // First fallback: should succeed for both reference and buggy
        vm.prank(address(this));
        (bool success1,) = address(c).call{value: 10 ether}("");
        assertTrue(success1, "First fallback should succeed");

        // Second call at same block timestamp (1) - without increment, after first call:
        // Reference: pastBlockTime becomes 2 after first call, so now timestamp(1) > pastBlockTime(2) is false => revert
        // Buggy: pastBlockTime stays 0, so timestamp(1) > 0 is true => passes
        // We'll capture revert bool via try/catch
        vm.prank(address(this));
        (bool success2,) = address(c).call{value: 10 ether}("");

        // In the reference, success2 should be false (revert)
        // In buggy, success2 should be true (no revert)
        // We assert success2 is false, which reference satisfies, bug breaks
        assertTrue(!success2, "Second fallback must revert");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set block.timestamp to a known value
        vm.warp(1000);
        // Set block.number so that block.number % 15 != 0 (e.g., block.number = 1)
        vm.roll(1);
        // Deal ether to an address and call fallback
        address alice = address(0x123);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        (bool success, ) = address(c).call{value: 10 ether}("");
        // The call should succeed (no revert)
        assertTrue(success);
        // After the call, pastBlockTime should be block.timestamp + 1 (reference) or +2 (bug)
        uint256 pt = c.pastBlockTime();
        // In the reference, it is 1001; in the bug, it is 1002
        // So assert that it is exactly 1001 (the correct value)
        assertTrue(pt == 1001);
    }
}
